/**
 * GENERATED IMAGE MANIFEST — PLACEHOLDER PHOTOGRAPHY
 * ------------------------------------------------------------------
 * Every photograph referenced here is licensed stock used ONLY to hold
 * the layout together for this concept. None of it shows Daima Civil
 * Engineering Works, its staff, its plant or its projects.
 *
 * TO GO LIVE:
 *   1. Drop Daima's own photographs into /public/img using these same keys.
 *   2. Update `alt` to describe the real photograph.
 *   3. Set `placeholder: false` and clear `credit`.
 *   4. Regenerate `blurDataURL` (any 16px-wide JPEG of the image, base64).
 * Anything still marked `placeholder: true` is listed automatically on
 * /content-notes, so nothing can quietly ship as if it were real.
 */

export type SiteImage = {
  /** Stable key. Also the filename: /public/img/<key>.jpg */
  key: string;
  src: string;
  alt: string;
  /** Intrinsic aspect ratio of the source file (w / h). */
  ratio: number;
  /** Dominant colour, painted behind the image while it loads. */
  color: string;
  blurDataURL: string;
  /** True while this is stock standing in for Daima's own photography. */
  placeholder: boolean;
  credit?: { name: string; url: string };
};

