export type ImageKey = keyof typeof IMAGES;

export const images = IMAGES as Record<ImageKey, SiteImage>;

export function img(key: ImageKey): SiteImage {
  return IMAGES[key];
}

/** Every image still standing in for real Daima photography. */
export function placeholderImages(): SiteImage[] {
  return Object.values(IMAGES).filter((i) => i.placeholder);
}

/** De-duplicated photographer credits, for the content-notes page. */
export function imageCredits(): { name: string; url: string; count: number }[] {
  const byName = new Map<string, { name: string; url: string; count: number }>();
  for (const i of Object.values(IMAGES)) {
    if (!i.credit) continue;
    const found = byName.get(i.credit.name);
    if (found) found.count += 1;
    else byName.set(i.credit.name, { ...i.credit, count: 1 });
  }
  return [...byName.values()].sort((a, b) => a.name.localeCompare(b.name));
}
